from pathlib import Path
import json
# Explicit route registry. Each route has one access/body policy and one service action.
rows=[]
def add(method,path,domain,name,expression,access='public',body=False,status=200,limit=False):rows.append(dict(method=method,path=path,domain=domain,name=name,expression=expression,access=access,body=body,status=status,limit=limit))
add('GET','','documentation','index','documentation.apiIndex()')
add('GET','openapi','documentation','specification','documentation.specification()')
add('GET','health','system','health','system.health()')
add('GET','ready','system','ready','system.readiness()')
for path,expr in [('wp1/home','gis.home()'),('wp1/search','gis.search(c.query)'),('wp1/areas','publicData.areas(c.query)'),('wp1/features','publicData.features(c.query)'),('wp1/nearby','publicData.nearby(c.query)'),('wp1/projects','publicData.projects(c.query)'),('wp1/projects/[id]','gis.publicProfile(c.params.id)'),('wp1/datasets','publicData.datasets()'),('wp1/datasets/[id]','catalogue.datasetDetail(c.params.id)'),('wp1/districts/[id]','catalogue.district(c.params.id,c.query)'),('wp1/districts/[id]/[domain]','gis.districtDomain(c.params.id,c.params.domain,c.query)'),('wp1/layers','gis.layers()'),('wp1/layers/[id]/features','gis.layerFeatures(c.params.id,c.query)'),('wp1/areas/[id]/boundary','gis.boundary(c.params.id)'),('wp1/files/[id]','files.publicDownload(c.params.id)'),('wp1/exports/[id]/[resource]','gis.exportDataset(c.params.id,c.params.resource,c.query)'),('reference/[kind]','catalogue.masters(c.params.kind)')]:add('GET',path,'explorer',path.replace('/','_').replace('[','').replace(']',''),expr)
for kind in ['resources','policies']:add('GET','wp1/'+kind,'explorer',kind,f"catalogue.catalogue('{kind}',c.query)")
add('GET','wp1/demo-project','explorer','demoProject',"getDemoProject()")
add('GET','wp1/information-layer','explorer','referenceLayer',"readReferencePack('layer')")
add('GET','wp1/information-layer/index','explorer','referenceIndex',"readReferencePack('index')")
add('POST','wp1/compare','explorer','compare','gis.compare(c.input)',body=True)
add('POST','wp2/estimate-energy','planning','estimateEnergy','({data:calculations.estimateEnergy(c.input)})',body=True)
add('GET','wp2/engines','planning','engines','({data:implementations.map(implementation=>({implementation,codeDigest:implementationDigest(implementation)}))})')
add('POST','wp2/assessments','planning','createAssessment','({data:await planning.createAssessment(c.input)})',body=True,status=201,limit=True)
for method,suffix,name,expr,body,status in [('GET','','assessment','planning.getAssessment(c.params.id,c.planningToken)',False,200),('POST','/scenarios','saveScenario','planning.saveScenario(c.params.id,c.planningToken,c.input)',True,201),('POST','/runs','runScenario','planning.runScenario(c.params.id,c.planningToken,c.input)',True,201),('GET','/runs','runs','planning.getRuns(c.params.id,c.planningToken)',False,200),('GET','/report','report','reporting.planningReport(c.params.id,c.planningToken)',False,200)]:add(method,'wp2/assessments/[id]'+suffix,'planning',name,'({data:await '+expr+'})','planning',body,status,method=='POST')
add('GET','auth/me','admin','me','({data:c.actor})','authenticated')
for method,path,name,expr,body,status in [('GET','internal/projects','projects','profiles.myProjects(c.actor!)',False,200),('POST','internal/projects','createProject','({data:await profiles.createProject(c.actor!,c.input)})',True,201),('GET','internal/projects/[id]','versions','system.projectVersions(c.actor!,c.params.id)',False,200),('GET','internal/profiles/[id]','profile','({data:await profiles.getProfile(c.actor!,c.params.id)})',False,200),('PATCH','internal/profiles/[id]','updateProfile','({data:await project.updateProfile(c.actor!,c.params.id,c.input)})',True,200),('POST','internal/profiles/[id]/notes','note','({data:await profiles.saveNote(c.actor!,c.params.id,c.input)})',True,200),('POST','internal/profiles/[id]/transition','transition','({data:await project.profileTransition(c.actor!,c.params.id,c.input)})',True,200),('POST','internal/profiles/[id]/revise','revise','({data:await project.reviseProfile(c.actor!,c.params.id,c.input)})',True,201)]:add(method,path,'projects',name,expr,'authenticated',body,status)
for method,path,name,expr,body,status in [('POST','files','upload','({data:await files.upload(c.actor!,c.request)})',False,201),('GET','files/[id]','download','files.download(c.actor!,c.params.id)',False,200),('POST','files/[id]/review','reviewFile','({data:await files.reviewFile(c.actor!,c.params.id,c.input)})',True,200)]:add(method,path,'files',name,expr,'authenticated',body,status)
add('GET','manage/resources','admin','resourceDefinitions','getResourceDefinitions(c)','authenticated')
for method,path,name,expr,body,status in [('GET','manage/resources/[resource]','listResources','resources.resourceList(c.actor!,c.params.resource,c.query)',False,200),('POST','manage/resources/[resource]','createResource','({data:await resources.resourceWrite(c.actor!,c.params.resource,c.input)})',True,201),('PATCH','manage/resources/[resource]/[id]','updateResource','({data:await resources.resourceWrite(c.actor!,c.params.resource,c.input,c.params.id)})',True,200),('DELETE','manage/resources/[resource]/[id]','deleteResource','({data:await resources.resourceWrite(c.actor!,c.params.resource,{},c.params.id,true)})',False,200)]:add(method,path,'admin',name,expr,'authenticated',body,status)
for method,path,name,expr,body,status in [('GET','admin/users','users','users.users(c.actor!)',False,200),('POST','admin/users','provision','({data:await users.provision(c.actor!,c.input)})',True,201),('POST','admin/users/[id]/deactivate','deactivate','({data:await users.deactivate(c.actor!,c.params.id)})',False,200),('POST','admin/projects/[id]/memberships','membership','({data:await users.membership(c.actor!,c.params.id,c.input)})',True,200),('GET','admin/audit','audit','governance.auditLog(c.actor!)',False,200),('POST','admin/reminders','reminders','({data:await users.reminders(c.actor!)})',False,200),('POST','admin/datasets/[id]/transition','datasetTransition','({data:await governance.datasetTransition(c.actor!,c.params.id,c.input)})',True,200),('POST','admin/definitions/[kind]/[id]','definitionApproval','({data:await governance.approveDefinition(c.actor!,c.params.kind,c.params.id,c.input)})',True,200),('POST','admin/imports','importFile','({data:await imports.runImport(c.actor!,c.input)})',True,201),('GET','admin/imports/[id]/rows','importRows','imports.importRows(c.actor!,c.params.id,c.query)',False,200),('POST','admin/issues/[id]/resolve','resolveIssue','({data:await imports.resolveIssue(c.actor!,c.params.id,c.input)})',True,200)]:add(method,path,'admin',name,expr,'authenticated',body,status)
for method,path,name,expr,body,status in [('GET','wp3/projects/[id]/obligations','obligations','({data:await facts.obligations(c.actor!,c.params.id)})',False,200),('GET','wp3/obligations/[id]/form','form','({data:await facts.form(c.actor!,c.params.id)})',False,200),('GET','wp3/projects/[id]/dashboard','dashboard','reporting.monitoringDashboard(c.actor!,c.params.id)',False,200),('POST','wp3/submissions','create','({data:await monitor.createDraft(c.actor!,c.input)})',True,201),('GET','wp3/submissions/[id]','submission','system.submission(c.actor!,c.params.id)',False,200),('PUT','wp3/submissions/[id]/values','saveValue','({data:await monitor.saveValue(c.actor!,c.params.id,c.input)})',True,200),('POST','wp3/submissions/[id]/transition','transition','({data:await monitor.transition(c.actor!,c.params.id,c.input)})',True,200),('POST','wp3/submissions/[id]/validate','validate','({data:await monitor.validateRevision(c.actor!,c.params.id)})',False,200),('POST','wp3/submissions/[id]/correct','correct','({data:await monitor.correction(c.actor!,c.params.id,c.input)})',True,201),('POST','wp3/submissions/[id]/release','release','({data:await reporting.release(c.actor!,c.params.id,c.input)})',True,200),('GET','wp3/submissions/[id]/history','history','reporting.history(c.actor!,c.params.id)',False,200),('GET','wp3/submissions/[id]/records/[kind]','records','({data:await facts.records(c.actor!,c.params.id,c.params.kind)})',False,200),('POST','wp3/submissions/[id]/records/[kind]','addRecord','({data:await facts.addRecord(c.actor!,c.params.id,c.params.kind,c.input)})',True,201),('DELETE','wp3/submissions/[id]/records/[kind]/[recordId]','deleteRecord','({data:await facts.deleteRecord(c.actor!,c.params.id,c.params.kind,c.params.recordId)})',False,200)]:add(method,path,'monitoring',name,expr,'authenticated',body,status)
for method,path,name,expr,body,status in [('GET','queries','queries','inquiries.listQueries(c.actor!)',False,200),('POST','queries','ask','({data:await inquiries.ask(c.actor!,c.input)})',True,201),('POST','queries/[id]/answer','answer','({data:await inquiries.answer(c.actor!,c.params.id,c.input)})',True,200),('GET','notifications','notifications','users.notifications(c.actor!)',False,200),('POST','notifications/[id]/read','read','({data:await users.acknowledge(c.actor!,c.params.id)})',False,200)]:add(method,path,'learning',name,expr,'authenticated',body,status)
imports={
'documentation':"import * as documentation from '@/services/documentation';",
'system':"import * as system from '@/services/system';",
'explorer':"import {readReferencePack} from '@/services/reference-pack';\nimport * as gis from '@/services/gis';\nimport * as publicData from '@/services/public-data';\nimport * as catalogue from '@/services/catalogue';\nimport * as files from '@/services/files';\nimport {ApiError} from '@/lib/http';\nasync function getDemoProject(){if(process.env.NODE_ENV!=='development')throw new ApiError(404,'NOT_FOUND','API route not found');return publicData.demoProject();}",
'planning':"import * as planning from '@/services/planning';\nimport * as calculations from '@/services/calculations';\nimport * as reporting from '@/services/reporting';\nimport {implementations,implementationDigest} from '@/services/planning-engines';",
'projects':"import * as profiles from '@/services/project-editor';\nimport * as project from '@/services/project-workflow';\nimport * as system from '@/services/system';",
'files':"import * as files from '@/services/files';",
'admin':"import * as resources from '@/services/resources';\nimport * as adminUsers from '@/services/administration';\nimport * as governance from '@/services/admin-workflow';\nimport * as imports from '@/services/imports';\nimport {admin} from '@/lib/governance';\nfunction getResourceDefinitions(c:RequestContext){admin(c.actor!);return {data:resources.resources};}",
'monitoring':"import * as facts from '@/services/monitoring-records';\nimport * as monitor from '@/services/monitoring';\nimport * as reporting from '@/services/reporting';\nimport * as system from '@/services/system';",
'learning':"import * as inquiries from '@/services/queries';\nimport * as users from '@/services/administration';"}
for domain in imports:
 funcs=[f"export async function {r['name']}(c:RequestContext){{return {r['expression'].replace('users.','adminUsers.') if domain=='admin' else r['expression']};}}" for r in rows if r['domain']==domain]
 Path(f'src/controllers/{domain}.controller.ts').write_text("import type {RequestContext} from '@/http/handler';\n"+imports[domain]+'\n'+'\n'.join(funcs)+'\n')
paths={}
for row in rows:paths.setdefault(row['path'],[]).append(row)
for path,operations in paths.items():
 dest=Path('src/app/api/v1')/path/'route.ts';dest.parent.mkdir(parents=True,exist_ok=True)
 text="import {route,options} from '@/http/handler';\n"+'\n'.join(f"import * as {domain} from '@/controllers/{domain}.controller';" for domain in sorted(set(x['domain'] for x in operations)))+"\nexport const runtime='nodejs';\nexport const dynamic='force-dynamic';\nexport const OPTIONS=options;\n"
 for r in operations:
  opts={'access':r['access'],'status':r['status']}
  if r['body']:opts['body']='json'
  if r['limit']:opts['planningLimit']=True
  text+=f"export const {r['method']}=route({json.dumps(opts)},{r['domain']}.{r['name']});\n"
 dest.write_text(text)
Path('src/generated/route-manifest.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='expression'} for r in rows],indent=2)+'\n')
print(len(rows),'operations in',len(paths),'explicit Next.js route modules')
